def appendAverage {n c s : Nat} (F : BinaryMatrix n (c + s) → Real)
    (M : BinaryMatrix n c) : Real :=
  uniformMean (fun B : BinaryMatrix n s => F (appendBinaryMatrix M B))

def appendZeroFrequency {n c s : Nat} (Y : BinaryMatrix n c) :
    BinaryMatrix n (c + s) :=
  appendBinaryMatrix Y 0

def fourierCoeff {n d : ℕ} (f : BinaryMatrix n d → ℝ)
    (Y : BinaryMatrix n d) : ℝ :=
  uniformMean (fun M => f M * character Y M)
